package com.wtm.ui;
import com.wtm.firstparty.*;import com.wtm.net.HttpService;import com.wtm.util.MiniJson;
import javax.swing.*;import javax.swing.border.*;import javax.swing.event.*;import javax.swing.table.*;import java.awt.*;import java.net.URLEncoder;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;import java.util.List;
public final class LocationsNetworkInjector{
 private LocationsNetworkInjector(){}public static void start(){javax.swing.Timer t=new javax.swing.Timer(500,e->scan());t.setInitialDelay(900);t.start();}
 private static void scan(){for(Window w:Window.getWindows())if(w instanceof JFrame f&&f.isDisplayable()&&f.getClass().getName().equals("com.wtm.ui.OperationsWorkspaceFrame"))inject(f);}
 private static void inject(JFrame f){try{var ar=f.getClass().getDeclaredField("activeWorkspaceRoute");ar.setAccessible(true);String route=String.valueOf(ar.get(f));if(!route.toLowerCase().contains("location"))return;var hf=f.getClass().getDeclaredField("workspaceContentHost");hf.setAccessible(true);JPanel host=(JPanel)hf.get(f);if(Boolean.TRUE.equals(host.getClientProperty("northstar.locations.188")))return;if(host.getComponentCount()==0)return;Component existing=host.getComponent(0);host.removeAll();NorthStarTabHost top=new NorthStarTabHost();top.addTab("Weather & Route Pins",wrapExisting(existing)).addTab("Logistics Network",network());host.add(top,BorderLayout.CENTER);host.putClientProperty("northstar.locations.188",Boolean.TRUE);NorthStarThemeCompliance.apply(host);host.revalidate();host.repaint();}catch(Exception ignored){}}
 private static JComponent wrapExisting(Component c){JPanel p=new JPanel(new BorderLayout());p.setBackground(Theme.bg());p.add(c);return p;}
 private static JComponent network(){JPanel root=new JPanel(new BorderLayout());root.setBackground(Theme.bg());root.setBorder(new EmptyBorder(8,4,4,4));NorthStarTabHost sub=new NorthStarTabHost();sub.addTab("Network Locations",locations()).addTab("Map Display",display()).addTab("Pin Styles",styles());root.add(sub);return root;}
 private static JComponent locations(){JPanel p=new JPanel(new BorderLayout(10,10));p.setBackground(Theme.bg());p.setBorder(new EmptyBorder(8,4,4,4));DefaultTableModel m=new DefaultTableModel(new Object[]{"Name","Category","Address","Network / Dealer ID","Facing LC","Latitude","Longitude","Geofence","Active"},0){public boolean isCellEditable(int r,int c){return c==4;}};JTable t=new JTable(m);t.setAutoCreateRowSorter(true);t.setRowHeight(28);TableRowSorter<DefaultTableModel> sorter=new TableRowSorter<>(m);t.setRowSorter(sorter);JLabel count=new JLabel();count.setForeground(Theme.muted());Runnable ref=()->{m.setRowCount(0);for(NetworkLocation n:NetworkLocationStore.get().all())m.addRow(new Object[]{n.name(),n.category(),n.address(),n.externalId(),FacingCenterStore.get(n),n.hasCoordinates()?n.latitude():"",n.hasCoordinates()?n.longitude():"",n.geofenceMeters()+" m",n.active()});count.setText(m.getRowCount()+" network locations loaded");};m.addTableModelListener(e->{if(e.getColumn()==4&&e.getFirstRow()>=0&&e.getFirstRow()<m.getRowCount()){String ext=String.valueOf(m.getValueAt(e.getFirstRow(),3));for(NetworkLocation n:NetworkLocationStore.get().all())if(Objects.equals(n.externalId(),ext)){FacingCenterStore.set(n,String.valueOf(m.getValueAt(e.getFirstRow(),4)));break;}}});
  JPanel top=new JPanel(new BorderLayout(8,8));top.setOpaque(false);JPanel toolbar=new JPanel(new FlowLayout(FlowLayout.LEFT,8,0));toolbar.setOpaque(false);JButton add=new JButton("Add Location"),imp=new JButton("Import / Update DVIEW CSV"),templ=new JButton("Export DVIEW Template"),geo=new JButton("Geocode Missing"),refresh=new JButton("Refresh Network"),del=new JButton("Delete Selected");for(JButton b:new JButton[]{add,imp,templ,geo,refresh,del})toolbar.add(b);top.add(toolbar,BorderLayout.NORTH);JPanel search=new JPanel(new BorderLayout(8,0));search.setOpaque(false);JLabel sl=new JLabel("Search network");sl.setForeground(Theme.text());JTextField q=new JTextField();q.setPreferredSize(new Dimension(280,32));search.add(sl,BorderLayout.WEST);search.add(q);search.add(count,BorderLayout.EAST);top.add(search,BorderLayout.SOUTH);p.add(top,BorderLayout.NORTH);JScrollPane sp=new JScrollPane(t);sp.setBorder(new LineBorder(Theme.border()));p.add(sp);JLabel h=new JLabel("Importing an updated DVIEW address list is an upsert: unchanged duplicates are ignored, changed locations are updated, and newly discovered dealers/logistics centers are added.");h.setForeground(Theme.muted());p.add(h,BorderLayout.SOUTH);q.getDocument().addDocumentListener(new DocumentListener(){void f(){String s=q.getText().trim();sorter.setRowFilter(s.isBlank()?null:RowFilter.regexFilter("(?i)"+java.util.regex.Pattern.quote(s)));}public void insertUpdate(DocumentEvent e){f();}public void removeUpdate(DocumentEvent e){f();}public void changedUpdate(DocumentEvent e){f();}});ref.run();
  add.addActionListener(e->addLocation(p,ref));imp.addActionListener(e->{Path path=NorthStarFileDialog.open(p,"Import / Update DVIEW Address CSV","csv");if(path!=null)try{int n=NetworkLocationStore.get().importCsv(path);info(p,"DVIEW network synchronized.\nNew or changed records: "+n+"\nTotal network locations: "+NetworkLocationStore.get().all().size());ref.run();}catch(Exception ex){err(p,ex);}});templ.addActionListener(e->{Path path=NorthStarFileDialog.save(p,"Export DVIEW Address Template","northstar-dview-address-template.csv");if(path!=null)try{NetworkLocationStore.get().exportTemplate(path);info(p,"Template saved to:\n"+path);}catch(Exception ex){err(p,ex);}});refresh.addActionListener(e->ref.run());geo.addActionListener(e->{int changed=0;for(NetworkLocation n:NetworkLocationStore.get().all())if(n.active()&&!n.hasCoordinates()&&!n.address().isBlank()){double[]ll=geocode(n.address());if(Double.isFinite(ll[0])){NetworkLocationStore.get().upsert(new NetworkLocation(n.id(),n.name(),n.category(),n.address(),n.externalId(),ll[0],ll[1],n.geofenceMeters(),n.notes(),n.active()));changed++;}}info(p,"Geocoded "+changed+" locations.");ref.run();});del.addActionListener(e->{int vr=t.getSelectedRow();if(vr<0)return;int r=t.convertRowIndexToModel(vr);String ext=String.valueOf(m.getValueAt(r,3));for(NetworkLocation n:NetworkLocationStore.get().all())if(Objects.equals(n.externalId(),ext)){NetworkLocationStore.get().delete(n.id());break;}ref.run();});NorthStarThemeCompliance.apply(p);return p;}
 private static JComponent display(){JPanel p=new JPanel(new BorderLayout(10,10));p.setBackground(Theme.bg());p.setBorder(new EmptyBorder(10,4,4,4));JTextArea help=new JTextArea("Choose which operational network layers appear on the Main Showcase and Truck Tracking Playback maps. Playback always keeps active route endpoints visible. Facing LC regions appear only when enough geocoded dealers have Facing LC assignments.");help.setEditable(false);help.setOpaque(false);help.setForeground(Theme.muted());help.setLineWrap(true);help.setWrapStyleWord(true);p.add(help,BorderLayout.NORTH);JPanel grid=new JPanel(new GridLayout(0,3,12,12));grid.setOpaque(false);grid.add(label("Map Layer"));grid.add(label("Main Showcase"));grid.add(label("Playback / Live Map"));row(grid,"Dealers",NetworkMapDisplaySettings.mainDealers(),NetworkMapDisplaySettings.playbackDealers(),NetworkMapDisplaySettings::mainDealers,NetworkMapDisplaySettings::playbackDealers);row(grid,"Logistics Centers",NetworkMapDisplaySettings.mainCenters(),NetworkMapDisplaySettings.playbackCenters(),NetworkMapDisplaySettings::mainCenters,NetworkMapDisplaySettings::playbackCenters);row(grid,"Other Logistics Addresses",NetworkMapDisplaySettings.mainOther(),NetworkMapDisplaySettings.playbackOther(),NetworkMapDisplaySettings::mainOther,NetworkMapDisplaySettings::playbackOther);row(grid,"Facing LC Service Regions",NetworkMapDisplaySettings.mainRegions(),NetworkMapDisplaySettings.playbackRegions(),NetworkMapDisplaySettings::mainRegions,NetworkMapDisplaySettings::playbackRegions);JPanel card=new JPanel(new BorderLayout());card.setBackground(Theme.panel());card.setBorder(new CompoundBorder(new LineBorder(Theme.border()),new EmptyBorder(18,18,18,18)));card.add(grid,BorderLayout.NORTH);p.add(card);NorthStarThemeCompliance.apply(p);return p;}
 private interface Setter{void set(boolean v);}private static void row(JPanel g,String n,boolean a,boolean b,Setter sa,Setter sb){g.add(label(n));JCheckBox x=new JCheckBox("Show",a),y=new JCheckBox("Show",b);x.setOpaque(false);y.setOpaque(false);x.setForeground(Theme.text());y.setForeground(Theme.text());x.addActionListener(e->sa.set(x.isSelected()));y.addActionListener(e->sb.set(y.isSelected()));g.add(x);g.add(y);}private static JLabel label(String s){JLabel l=new JLabel(s);l.setForeground(Theme.text());l.setFont(new Font(Font.SANS_SERIF,Font.BOLD,13));return l;}
 private static JComponent styles(){JPanel p=new JPanel(new BorderLayout(8,8));p.setBackground(Theme.bg());DefaultTableModel m=new DefaultTableModel(new Object[]{"Location Category","Map Pin Style"},0){public boolean isCellEditable(int r,int c){return c==1;}};for(String c:NetworkPinStyleRegistry.CATEGORIES)m.addRow(new Object[]{c,NetworkPinStyleRegistry.style(c)});JTable t=new JTable(m);t.setRowHeight(30);JComboBox<String> combo=new JComboBox<>(NetworkPinStyleRegistry.STYLES);t.getColumnModel().getColumn(1).setCellEditor(new DefaultCellEditor(combo));m.addTableModelListener(e->{if(e.getColumn()==1&&e.getFirstRow()>=0)NetworkPinStyleRegistry.set(String.valueOf(m.getValueAt(e.getFirstRow(),0)),String.valueOf(m.getValueAt(e.getFirstRow(),1)));});JTextArea help=new JTextArea("Pin styles are shared by Main Showcase and Playback maps. Location visibility is controlled separately in Map Display.");help.setEditable(false);help.setOpaque(false);help.setForeground(Theme.muted());help.setLineWrap(true);help.setWrapStyleWord(true);p.add(help,BorderLayout.NORTH);p.add(new JScrollPane(t));NorthStarThemeCompliance.apply(p);return p;}
 private static void addLocation(Component owner,Runnable ref){Window w=SwingUtilities.getWindowAncestor(owner);JDialog d=new JDialog(w,"Add Network Location",Dialog.ModalityType.APPLICATION_MODAL);JPanel root=new JPanel(new BorderLayout(12,12));root.setBackground(Theme.bg());root.setBorder(new EmptyBorder(18,18,18,18));d.setContentPane(root);JTextField name=new JTextField(),addr=new JTextField(),ext=new JTextField(),face=new JTextField(),gf=new JTextField("500");JComboBox<String> cat=new JComboBox<>(NetworkPinStyleRegistry.CATEGORIES);JPanel form=new JPanel(new GridLayout(0,2,10,12));form.setBackground(Theme.panel());form.setBorder(new CompoundBorder(new LineBorder(Theme.border()),new EmptyBorder(16,16,16,16)));Object[][] rows={{"Name",name},{"Category",cat},{"Street address / city",addr},{"Dealer / network ID",ext},{"Facing LC",face},{"Geofence meters",gf}};for(Object[]r:rows){JLabel l=new JLabel(String.valueOf(r[0]));l.setForeground(Theme.text());form.add(l);form.add((Component)r[1]);}root.add(form);JPanel acts=new JPanel(new FlowLayout(FlowLayout.RIGHT,8,0));acts.setOpaque(false);JButton cancel=new JButton("Cancel"),ok=new JButton("Add Location");acts.add(cancel);acts.add(ok);root.add(acts,BorderLayout.SOUTH);cancel.addActionListener(e->d.dispose());ok.addActionListener(e->{if(name.getText().isBlank())return;double[]ll=geocode(addr.getText().trim());int g=500;try{g=Integer.parseInt(gf.getText().trim());}catch(Exception ignored){}NetworkLocation n=new NetworkLocation(UUID.randomUUID().toString(),name.getText().trim(),String.valueOf(cat.getSelectedItem()),addr.getText().trim(),ext.getText().trim(),ll[0],ll[1],g,"",true);NetworkLocationStore.get().upsert(n);FacingCenterStore.set(n,face.getText());ref.run();d.dispose();});NorthStarThemeCompliance.apply(root);d.setSize(650,470);d.setLocationRelativeTo(owner);d.getRootPane().setDefaultButton(ok);d.setVisible(true);}
 private static double[]geocode(String a){if(a.isBlank())return new double[]{Double.NaN,Double.NaN};try{String u="https://nominatim.openstreetmap.org/search?format=jsonv2&limit=1&q="+URLEncoder.encode(a,StandardCharsets.UTF_8);List<Object>x=MiniJson.arr(MiniJson.parse(new HttpService().getText(u)));if(x.isEmpty())return new double[]{Double.NaN,Double.NaN};Map<String,Object>o=MiniJson.obj(x.get(0));return new double[]{Double.parseDouble(MiniJson.str(o.get("lat"))),Double.parseDouble(MiniJson.str(o.get("lon")))};}catch(Exception e){return new double[]{Double.NaN,Double.NaN};}}
 private static void err(Component c,Exception e){JOptionPane.showMessageDialog(c,e.getMessage(),"NorthStar Locations",JOptionPane.ERROR_MESSAGE);}private static void info(Component c,String s){JOptionPane.showMessageDialog(c,s,"NorthStar Locations",JOptionPane.INFORMATION_MESSAGE);}
}
